import{c as t,Q as a,j as s,m as n}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Self-Harness: Harnesses That Improve Themselves","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.09498","title":"Self-Harness: Harnesses That Improve Themselves","archived_date":"2026-06-14T00:00:00.000Z","arxiv_id":2606.09498,"authors":["Hangfan Zhang","Shao Zhang","Kangcong Li","Chen Zhang","Yang Chen","Yiqun Zhang","Lei Bai","Shuyue Hu"],"domains":["cs.CL"],"pdf_path":"pdfs/2606.09498.pdf","published_date":"2026-06-08T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-08-self-harness-harnesses-improve-themselves-2606-09498.md","filePath":"research/papers/2026-06-08-self-harness-harnesses-improve-themselves-2606-09498.md","lastUpdated":1785909234000}'),i={name:"research/papers/2026-06-08-self-harness-harnesses-improve-themselves-2606-09498.md"};function r(o,e,l,d,h,c){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="self-harness-harnesses-that-improve-themselves" tabindex="-1">Self-Harness: Harnesses That Improve Themselves <a class="header-anchor" href="#self-harness-harnesses-that-improve-themselves" aria-label="Permalink to &quot;Self-Harness: Harnesses That Improve Themselves&quot;">​</a></h1><p><strong>Authors</strong>: Hangfan Zhang, Shao Zhang, Kangcong Li, Chen Zhang, Yang Chen, Yiqun Zhang, Lei Bai, Shuyue Hu <strong>Published</strong>: June 8, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.09498" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.09498</a><strong>arXiv ID</strong>: 2606.09498 <strong>Categories</strong>: cs.CL <strong>PDF</strong>: <a href="https://arxiv.org/abs/2606.09498" target="_blank" rel="noreferrer">research/papers/pdfs/2606.09498.pdf</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>The performance of LLM-based agents is jointly shaped by their base models and the harnesses that mediate their interaction with the environment. Because different models exhibit distinct behaviors, effective harness design is inherently model-specific. Yet agent harnesses are still largely engineered by human experts, a paradigm that scales poorly as modern LLMs become increasingly diverse and rapidly evolving. In this paper, we introduce Self-Harness, a new paradigm in which an LLM-based agent improves its own operating harness, without relying on human engineers or stronger external agents. We operationalize Self-Harness as an iterative loop with three stages: Weakness Mining, which identifies model-specific failure patterns from execution traces; Harness Proposal, which generates diverse yet minimal harness modifications tied to these failures; and Proposal Validation, which accepts candidate edits only after regression testing. We instantiate Self-Harness on Terminal-Bench-2.0 using a minimal initial harness and three base models from diverse families: MiniMax M2.5, Qwen3.5-35B-A3B, and GLM-5. Across all three models, Self-Harness consistently improves performance, with held-out pass rates increasing from 40.5% to 61.9%, 23.8% to 38.1%, and 42.9% to 57.1%, respectively. Qualitative analyses further show that Self-Harness does not simply add generic instructions, but effectively turns model-specific weaknesses into concrete, executable harness changes. These results suggest a path toward LLM-based agents that are not merely shaped by their harnesses, but can also participate in reshaping them.</p><hr><h2 id="_1-introduction" tabindex="-1">1. Introduction <a class="header-anchor" href="#_1-introduction" aria-label="Permalink to &quot;1. Introduction&quot;">​</a></h2><p>LLM-based agents are shaped by both their base models and their &quot;harnesses&quot;—the surrounding systems mediating model-environment interaction. A harness includes system prompts, tools, runtime mechanisms, verification rules, and failure-recovery procedures. While harnesses have historically been engineered by human experts, this approach &quot;does not scale well with the diversity and rapid evolution of modern LLMs.&quot;</p><p>The paper proposes Self-Harness: enabling agents to improve the harness governing their own behavior. Unlike Meta-Harness (which uses stronger external agents) or human engineering, Self-Harness internalizes improvement within the target agent itself. This reduces dependence on external guidance and aligns harness changes to the specific model&#39;s failure modes.</p><p>The improvement loop repeatedly converts behavioral evidence into harness updates:</p><ul><li><strong>Weakness Mining</strong>: Cluster failed execution traces to identify model-specific failure patterns</li><li><strong>Harness Proposal</strong>: Generate diverse yet minimal modifications tied to specific failures</li><li><strong>Proposal Validation</strong>: Accept edits only after regression testing on held-out tasks</li></ul><h3 id="key-contributions" tabindex="-1">Key Contributions <a class="header-anchor" href="#key-contributions" aria-label="Permalink to &quot;Key Contributions&quot;">​</a></h3><ol><li>A novel paradigm enabling agents to design and refine their own harnesses without human engineering or external agent guidance</li><li>An operationalized iterative loop converting execution evidence into model-specific harness updates</li><li>Experiments showing improvements across three diverse models with absolute gains up to 21.4 pp and relative improvements up to 60%</li></ol><hr><h2 id="_2-background-and-related-work" tabindex="-1">2. Background and Related Work <a class="header-anchor" href="#_2-background-and-related-work" aria-label="Permalink to &quot;2. Background and Related Work&quot;">​</a></h2><h3 id="from-prompts-to-agent-harnesses" tabindex="-1">From Prompts to Agent Harnesses <a class="header-anchor" href="#from-prompts-to-agent-harnesses" aria-label="Permalink to &quot;From Prompts to Agent Harnesses&quot;">​</a></h3><p>The concept of &quot;harness&quot; encompasses the broader execution infrastructure beyond static prompts. Prompt engineering demonstrates that fixed models respond to instructions, demonstrations, retrieved evidence, memory mechanisms, and dynamically constructed inputs. Agentic systems extend this to full execution environments where models act, observe consequences, use tools, and receive feedback.</p><p>ReAct, SWE-agent, Claude Code, and similar systems illustrate how surrounding mechanisms shape agent behavior. The paper defines harness as &quot;prompts, tools, memory, verification rules, permission policies, adapters, and runtime mechanisms that mediate between the model and the environment.&quot;</p><h3 id="self-improving-agents-and-automated-agent-design" tabindex="-1">Self-Improving Agents and Automated Agent Design <a class="header-anchor" href="#self-improving-agents-and-automated-agent-design" aria-label="Permalink to &quot;Self-Improving Agents and Automated Agent Design&quot;">​</a></h3><p>Prior work studies systems adapting their inputs, memories, or workflows over time (Reflexion, agentic context engineering, STOP). A second line optimizes designs externally through search over agent designs or harness code optimization (Meta-Harness). Scientific discovery systems (The AI Scientist, AlphaEvolve) automate broader self-improvement loops.</p><p>Self-Harness differs by studying whether a fixed model under its current harness can propose bounded changes to the harness governing future behavior, without external optimization or stronger agents.</p><hr><h2 id="_3-self-harness-an-iterative-loop-for-model-specific-harness-improvement" tabindex="-1">3. Self-Harness: An Iterative Loop for Model-Specific Harness Improvement <a class="header-anchor" href="#_3-self-harness-an-iterative-loop-for-model-specific-harness-improvement" aria-label="Permalink to &quot;3. Self-Harness: An Iterative Loop for Model-Specific Harness Improvement&quot;">​</a></h2><h3 id="_3-1-preliminary" tabindex="-1">3.1 Preliminary <a class="header-anchor" href="#_3-1-preliminary" aria-label="Permalink to &quot;3.1 Preliminary&quot;">​</a></h3><p>Let <strong>M</strong> denote a fixed language model and <strong>h</strong> an agent harness. Given task instance <strong>x</strong>, running M under harness h produces execution trace τ and output y. An evaluator then assigns behavioral outcome (pass/fail). Self-Harness operates over a lineage of harnesses h₀, h₁, … where each transition represents a bounded edit rather than model weight updates.</p><h3 id="_3-2-weakness-mining-identifying-failure-patterns-from-clustered-execution-traces" tabindex="-1">3.2 Weakness Mining: Identifying Failure Patterns from Clustered Execution Traces <a class="header-anchor" href="#_3-2-weakness-mining-identifying-failure-patterns-from-clustered-execution-traces" aria-label="Permalink to &quot;3.2 Weakness Mining: Identifying Failure Patterns from Clustered Execution Traces&quot;">​</a></h3><p>The first stage converts failures into structured evidence. After running the model on held-in tasks, the evaluation system:</p><ol><li>Identifies failed records where the evaluator rejected the run</li><li>Analyzes each failure trace to extract the terminal failure reason, agent behavior connected to it, and causal status</li><li>Creates failure signatures φ(rᵢ) = (cᵢ, qᵢ, mᵢ) capturing: terminal cause, causal status, and abstract agent mechanism</li><li>Clusters failures by exact signature agreement</li></ol><p>This deterministic, evaluator-grounded clustering aggregates failures admitting the same harness-level intervention. The output is an evidence bundle <strong>B_t</strong> summarizing dominant failure patterns without prescribing specific edits.</p><h3 id="_3-3-harness-proposal-exploring-diverse-yet-minimal-candidate-modifications" tabindex="-1">3.3 Harness Proposal: Exploring Diverse yet Minimal Candidate Modifications <a class="header-anchor" href="#_3-3-harness-proposal-exploring-diverse-yet-minimal-candidate-modifications" aria-label="Permalink to &quot;3.3 Harness Proposal: Exploring Diverse yet Minimal Candidate Modifications&quot;">​</a></h3><p>Given evidence bundle B_t, the proposal stage invokes the same fixed model in a &quot;proposer role&quot; with bounded context: editable harness surfaces, verifier-grounded failure patterns, records of passing behaviors, and summaries of previous attempts.</p><p>The proposer generates <strong>K</strong> mutually distinct proposal bundles:</p><p><strong>P_t = {(Δⱼ, aⱼ)}ⱼ₌₁ᴷ</strong> where:</p><ul><li>Δⱼ maps current harness to candidate harness h_t^(j) = Δⱼ(h_t)</li><li>aⱼ is an audit record describing targeted pattern, edited surface, expected effect, and risks</li></ul><p>Diversity is encouraged across proposals (different patterns, surfaces, or hypotheses), while minimality is enforced within each (only change surfaces needed to address the mechanism).</p><h3 id="_3-4-proposal-validation-ensuring-robust-improvement-through-regression-testing" tabindex="-1">3.4 Proposal Validation: Ensuring Robust Improvement through Regression Testing <a class="header-anchor" href="#_3-4-proposal-validation-ensuring-robust-improvement-through-regression-testing" aria-label="Permalink to &quot;3.4 Proposal Validation: Ensuring Robust Improvement through Regression Testing&quot;">​</a></h3><p>Each candidate is evaluated on both held-in and held-out splits.</p><p><strong>Acceptance rule</strong>: Promote candidate h_t^(j) only if:</p><ul><li>Δᵢₙ^(j) ≥ 0 (no held-in degradation)</li><li>Δₕₒ^(j) ≥ 0 (no held-out degradation)</li><li>max(Δᵢₙ^(j), Δₕₒ^(j)) &gt; 0 (at least one split improves)</li></ul><p>This conservative rule rejects proposals trading improvement on one split against degradation on another. Multiple compatible candidates are merged; rejected candidates remain logged without changing the active harness.</p><hr><h2 id="_4-experiments" tabindex="-1">4. Experiments <a class="header-anchor" href="#_4-experiments" aria-label="Permalink to &quot;4. Experiments&quot;">​</a></h2><h3 id="_4-1-setup" tabindex="-1">4.1 Setup <a class="header-anchor" href="#_4-1-setup" aria-label="Permalink to &quot;4.1 Setup&quot;">​</a></h3><p><strong>Benchmark</strong>: Terminal-Bench-2.0, containing 89 containerized terminal tasks. The evaluation uses a fixed 64-case subset excluding tasks depending on unstable external resources or requiring unsupported multimodal inputs.</p><p><strong>Models</strong>:</p><ul><li>MiniMax M2.5</li><li>Qwen3.5-35B-A3B</li><li>GLM-5</li></ul><p><strong>Harness</strong>: Built on DeepAgent SDK with intentionally minimal design: short system prompt and default filesystem/shell tools. Self-Harness can only modify configuration points declaring instruction, tools, verification guidance, etc.</p><p><strong>Splits and Protocol</strong>: Tasks partitioned into held-in (supplies failure evidence) and held-out (regression testing only) before running Self-Harness. Task splits fixed across variants; each task starts fresh.</p><p><strong>Metrics</strong>: Primary metric is Pass (%), computed over two repeated attempts per harness candidate.</p><p><strong>Model Inference Services</strong>:</p><ul><li>MiniMax M2.5: Hosted API</li><li>Qwen3.5-35B-A3B: Local deployment on four NVIDIA H200 GPUs using SGLang v0.5.12-cu129</li><li>GLM-5: OpenRouter hosted endpoint</li></ul><p><strong>Terminal-Bench-2.0 Configuration</strong>:</p><ul><li>Execution environment: Harbor framework</li><li>Hardware: 64 CPU cores, 256 GB memory, 2 MB/s network bandwidth cap</li><li>Concurrency: 32 tasks (MiniMax/GLM-5), 48 tasks (Qwen3.5)</li></ul><h3 id="_4-2-main-results" tabindex="-1">4.2 Main Results <a class="header-anchor" href="#_4-2-main-results" aria-label="Permalink to &quot;4.2 Main Results&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Model</th><th>Initial</th><th>Final</th><th>Absolute Gain</th><th>Relative Gain</th></tr></thead><tbody><tr><td>MiniMax M2.5</td><td>40.5%</td><td>61.9%</td><td>+21.4 pp</td><td>+53%</td></tr><tr><td>Qwen3.5-35B-A3B</td><td>23.8%</td><td>38.1%</td><td>+14.3 pp</td><td>+60%</td></tr><tr><td>GLM-5</td><td>42.9%</td><td>57.1%</td><td>+14.2 pp</td><td>+33%</td></tr></tbody></table><p>All three backends improve on held-out splits without degrading either split, supporting the design goal that proposed edits target reusable mechanisms rather than case-specific failures.</p><h3 id="_4-3-harness-evolution-and-retained-edits" tabindex="-1">4.3 Harness Evolution and Retained Edits <a class="header-anchor" href="#_4-3-harness-evolution-and-retained-edits" aria-label="Permalink to &quot;4.3 Harness Evolution and Retained Edits&quot;">​</a></h3><p><strong>MiniMax M2.5</strong> (held-in: 42.2% → 53.9%):</p><ul><li>Creates required outputs earlier in execution</li><li>Handles structured tool content more carefully</li><li>Prevents stalled tool-use loops through bounded execution</li></ul><p><strong>Qwen3.5-35B-A3B</strong> (held-in: 20.3% → 36.7%):</p><ul><li>Emphasizes artifact checking and recovery</li><li>Improves retry discipline after failures</li><li>Adds tool-error-triggered middleware</li></ul><p><strong>GLM-5</strong> (held-in: 46.1% → 57.0%):</p><ul><li>Preserves environment changes across shell commands</li><li>Encourages transition from exploration to implementation/testing</li><li>Maintains session-scoped tool context</li></ul><p>While all models benefit from improved artifact reliability, the specific mechanisms differ — indicating model-specific adaptation rather than generic improvement.</p><h3 id="_4-4-trace-level-analysis" tabindex="-1">4.4 Trace-Level Analysis <a class="header-anchor" href="#_4-4-trace-level-analysis" aria-label="Permalink to &quot;4.4 Trace-Level Analysis&quot;">​</a></h3><p><strong>MiniMax M2.5 example</strong> (count-dataset-tokens task): Initial harness continues dataset exploration after finding relevant metadata and times out. Edited harness identifies metadata-backed subset, computes token total, writes answer artifact, and verifies — completing the task successfully.</p><p><strong>Qwen3.5-35B-A3B example</strong> (extract-elf task): Initial harness creates required script but enters repeated overwrite/edit failures, eventually deleting the required artifact before stopping. Edited harness uses tool-error-triggered recovery to recreate the script, fix parsing logic, validate JSON output, and preserve the required file.</p><p><strong>GLM-5 example</strong> (build-pov-ray task): Initial harness engages in long monolithic downloads consuming large budgets, then finalizes despite repeated sanity check failures. Edited harness uses bounded staged operations, checks archive evidence before committing work, and repairs failing checks before completion.</p><hr><h2 id="_5-conclusion" tabindex="-1">5. Conclusion <a class="header-anchor" href="#_5-conclusion" aria-label="Permalink to &quot;5. Conclusion&quot;">​</a></h2><p>The paper demonstrates that harness improvement should be treated as empirical state transitions. Useful edits must specify target behavior, modified surfaces, motivating evidence, and evaluation results justifying promotion.</p><p>Key findings:</p><ul><li>Keeping model, evaluator, and benchmark protocol fixed isolates whether improvements come from harness changes</li><li>Sparse initial harnesses can support self-improvement with proposals constrained by execution evidence and validated by regression testing</li><li>Self-Harness produces small, auditable, reversible changes rather than broad rewrites</li></ul><p><strong>Limitations</strong>:</p><ul><li>Studies bounded edits under fixed benchmarks, not open-ended improvement</li><li>Accepted edits may reflect benchmark-specific patterns</li><li>Depends on verifier quality and trace records</li><li>Pass-rate non-regression alone insufficient for higher-stakes changes</li></ul><hr><h2 id="quantified-conditions" tabindex="-1">Quantified Conditions <a class="header-anchor" href="#quantified-conditions" aria-label="Permalink to &quot;Quantified Conditions&quot;">​</a></h2><ul><li><strong>Acceptance gate</strong>: Δᵢₙ ≥ 0 AND Δₕₒ ≥ 0 AND max(Δᵢₙ, Δₕₒ) &gt; 0</li><li><strong>Evaluation dataset</strong>: Terminal-Bench-2.0, 64-task subset (multimodal tasks excluded)</li><li><strong>Convergence condition</strong>: no formal convergence criterion; if no candidates pass validation in a round, harness unchanged and loop continues</li></ul><hr><h2 id="relevance-to-the-loop-harness-self-improvement" tabindex="-1">Relevance to The Loop (harness self-improvement) <a class="header-anchor" href="#relevance-to-the-loop-harness-self-improvement" aria-label="Permalink to &quot;Relevance to The Loop (harness self-improvement)&quot;">​</a></h2><p>Self-Harness is a direct empirical proof-of-concept for the workspace&#39;s RECORD → self-evolution feedback path in core.md: an agent can mine its own failure traces, propose targeted harness patches, and validate them against regression without human intervention. The verifier-grounded failure signature clustering (terminal cause + behavior status + mechanism) maps precisely to the workspace&#39;s structured reflection → lesson → GOTCHAS.md pattern. The strict non-degradation acceptance gate (Δin ≥ 0, Δho ≥ 0) operationalizes the core.md §RECORD &quot;eval ≥5pp → git revert&quot; regression guard. Notably, the system uses the same model to both implement and propose harness changes — validating the workspace design where the implementer model is also the self-improver, not requiring an external stronger model.</p>',81)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
